package com.google.javascript.rhino;

import com.google.javascript.rhino.JSDocInfo.Visibility;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Set;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import org.mockito.internal.util.reflection.FieldSetter;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class JSDocInfoBuilder_addAuthor_TriageGen2Test {

    private JSDocInfoBuilder jsDocInfoBuilder;
    private com.google.javascript.rhino.JSDocInfo currentInfoMock;

    @Before
    public void setUp() throws Exception {
        // Initialize the builder
        jsDocInfoBuilder = new JSDocInfoBuilder(true);

        // Since currentInfo is likely a private field, we use reflection to inject a mock
        // to control the behavior of documentAuthor(author)
        currentInfoMock = mock(com.google.javascript.rhino.JSDocInfo.class);

        // Using a common reflection approach to set the private field 'currentInfo'
        java.lang.reflect.Field field = JSDocInfoBuilder.class.getDeclaredField("currentInfo");
        field.setAccessible(true);
        field.set(jsDocInfoBuilder, currentInfoMock);
    }

    /**
     * Tests the branch where currentInfo.documentAuthor(author) returns true.
     * This covers the 'if' block, sets 'populated' to true, and returns true.
     */
    @Test
    public void testAddAuthor_ReturnsTrueWhenAuthorExists() {
        String authorName = "John Doe";
        when(currentInfoMock.documentAuthor(authorName)).thenReturn(true);

        boolean result = jsDocInfoBuilder.addAuthor(authorName);

        assertTrue("addAuthor should return true when the author is already documented", result);
        assertTrue("isPopulated should return true after a successful addAuthor call", jsDocInfoBuilder.isPopulated());
    }

    /**
     * Tests the branch where currentInfo.documentAuthor(author) returns false.
     * This covers the 'else' block and returns false.
     */
    @Test
    public void testAddAuthor_ReturnsFalseWhenAuthorDoesNotExist() {
        String authorName = "Unknown Author";
        when(currentInfoMock.documentAuthor(authorName)).thenReturn(false);

        boolean result = jsDocInfoBuilder.addAuthor(authorName);

        assertFalse("addAuthor should return false when the author is not documented", result);
        // Note: Depending on implementation, isPopulated might remain false if it wasn't set before
        // This ensures we strictly follow the logic provided in the snippet
    }

    /**
     * Tests with a null parameter to ensure the method handles it based on currentInfo's logic.
     */
    @Test
    public void testAddAuthor_WithNullAuthor() {
        when(currentInfoMock.documentAuthor(null)).thenReturn(false);

        boolean result = jsDocInfoBuilder.addAuthor(null);

        assertFalse("addAuthor should return false if documentAuthor returns false for null", result);
    }

    /**
     * Tests the case where populated is already true, ensuring the logic still holds.
     */
    @Test
    public void testAddAuthor_WhenAlreadyPopulated() {
        // Setting up a scenario where it is already populated via another method is hard without knowing internals,
        // so we rely on the fact that if documentAuthor is true, populated becomes true.
        String authorName = "Existing Author";
        when(currentInfoMock.documentAuthor(authorName)).thenReturn(true);

        jsDocInfoBuilder.addAuthor(authorName);
        assertTrue(jsDocInfoBuilder.isPopulated());

        // Call again
        boolean result = jsDocInfoBuilder.addAuthor(authorName);
        assertTrue("Subsequent calls with same author should still return true", result);
        assertTrue("isPopulated should remain true", jsDocInfoBuilder.isPopulated());
    }
}
